"""COMBINATION m640_a0p1: RES=640 MOSAIC=1 ACC=0 PREC_FIRST=1 BOX=nbml NMS=0.45 (generated by ~/work/combos/make_combos.py
from ~/work/chanyoung/matrix/sub_matrix.py). Self-contained: model, raw heads and patch_cfg are this folder's copies.
RES / MOSAIC / ACC / PREC_FIRST are PINNED below (env cannot change them); the other knobs keep their env defaults.

Original header:

One submission file for every NON-kernel lever, so the matrix is a pure env sweep. Nick's custom kernels
(H11, H14-H17) are deliberately NOT used: the goal is to pick the input size first, then build kernels for it.

Base: Mo's per-resolution folder ~/work/res/r<RES> (own model copy incl. the 640 conv9 fix, library Mish in
fast mode) + raw heads (rmcat, H3) + numba box step (H4) + GC freeze (H5) + overlapped post (H2) + I5 (H13)
+ Nick's config-only patch (H18).

    RES=320|384|512|640         card input size
    MOSAIC=0|1                  1: 4 photos stretched to RES/2 (MOSAIC_TILE), tiled 2x2 (no gap) into one RES canvas,
                                one card pass per 4 photos. m640 = 4 x 320, m512 = 4 x 256, m384 = 4 x 192. Box ownership: a YOLO box centre
                                always lies in the grid cell that predicted it, so each tile's cells are
                                regrouped into an exact tile-sized head set and decoded with the normal box step.
    ACC=1|0                     fp32 accumulation in every conv (folder default 1; 0 = stock per-layer value)
    PREC_FIRST=0|1              first conv: bf16 weights + HiFi4 + fp32 acc (Mo, hwopt/03)
    CFG=1|0                     H18 (CFG_HALO CFG_NOINMOVE CFG_NOADD CFG_IO =1 unless set explicitly)
    BOX=nbml|nb  NMS=0.55       numba box step, multi-/single-label, NMS IoU
    BOXV=off|v2                 box-step variant (opt-in, ~/work/chanyoung/boxstep/BOXSTEP.md): v2 = rank by
                                sigmoid(obj)^0.5*sigmoid(cls)^1.25, fused box voting IoU>0.75, mosaic tile-edge
                                penalty 0.5 (rawheads_nb2.py); off = card kernel rawheads_nb.py (default)
    CHUNK_HEAD=8,16 CHUNK_TAIL=16,8
                                I5 card-pass schedule in photos (mosaic: divided by 4). Empty string = off.
    CHUNK (32) / MOSAIC_CHUNK (8 canvases)  steady-state pass size
    DUMP_RAW=prefix             keep the last run's raw heads; teardown writes prefix.u.npy + prefix.json
    DUMP_DETS=path.pkl          pickle the last run's detections
    RH_MEM=l1|dram              where the packed heads live on the card
    GC=freeze|on
"""
import gc
import importlib.util
import json
import os
import sys

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
COMBO = "m640_a0p1"
for _k, _v in dict(RES="640", MOSAIC="1", ACC="0", PREC_FIRST="1").items():
    os.environ[_k] = _v          # pinned: this folder IS this combination
os.environ.pop("MOSAIC_TILE", None)
os.environ.setdefault("BOX", "nbml")
os.environ.setdefault("NMS", "0.45")


def _e(k, d=""):
    return os.environ.get(k, d).strip()


def _ints(s):
    return [int(v) for v in s.split(",") if v.strip()]


RES = int(_e("RES", "320"))
MOSAIC = _e("MOSAIC", "0") == "1"
ACC = _e("ACC", "1") == "1"
PREC_FIRST = _e("PREC_FIRST", "0") == "1"
CFG = _e("CFG", "1") == "1"
BOX = _e("BOX", "nbml")
NMS = float(_e("NMS", "0.55"))
GCMODE = _e("GC", "freeze")
HEAD = _ints(os.environ.get("CHUNK_HEAD", "8,16"))
TAIL = _ints(os.environ.get("CHUNK_TAIL", "16,8"))
MCHUNK = int(_e("MOSAIC_CHUNK", "8"))
DUMP_RAW = _e("DUMP_RAW")
TILE = int(_e("MOSAIC_TILE", str(RES // 2))) if MOSAIC else 320   # 2x2 tiles fill the RES canvas
if MOSAIC and (RES != 2 * TILE or TILE % 32):
    raise ValueError(f"sub_matrix: MOSAIC=1 needs RES={2 * TILE}, got {RES}")
if BOX not in ("nb", "nbml"):
    raise ValueError(f"sub_matrix: BOX={BOX} not in nb/nbml")
os.environ["POST"] = "raw"
if CFG:
    for _k in ("CFG_HALO", "CFG_NOINMOVE", "CFG_NOADD", "CFG_IO"):
        os.environ.setdefault(_k, "1")

FOLDER = HERE
_spec = importlib.util.spec_from_file_location(f"res{RES}_submission", os.path.join(FOLDER, "res_submission.py"))
res = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(res)          # shadow model on sys.path, Mish fast mode, forced fp32 acc, RESOLUTION

import ttnn  # noqa: E402
import models.tt_cnn.tt.builder as builder  # noqa: E402

_c2_folder = builder.to_conv2d_config


def _is_first(cfg):
    return cfg.in_channels in (3, 16)      # the conv reading the (16-padded) photo


def _compute_config(cfg, device):
    sens = PREC_FIRST and _is_first(cfg)
    return ttnn.init_device_compute_kernel_config(
        device.arch(),
        math_fidelity=ttnn.MathFidelity.HiFi4 if sens else cfg.math_fidelity,
        fp32_dest_acc_en=True if (ACC or sens) else cfg.fp32_dest_acc_en,
        packer_l1_acc=cfg.packer_l1_acc)


def _conv2d_config(cfg):
    c = _c2_folder(cfg)
    if PREC_FIRST and _is_first(cfg):
        c.weights_dtype = ttnn.bfloat16
    return c


builder.to_compute_config = _compute_config
builder.to_conv2d_config = _conv2d_config

import rawheads_model as rh  # noqa: E402  (patches the folder's shadow TtYOLOv4, already on sys.path)
import rawheads_nb as rn  # noqa: E402
assert FOLDER in sys.modules[rh.TtYOLOv4.__module__].__file__, "raw heads patched the wrong model copy"
rh.install("rmcat")
rn.warm()
BOXV = _e("BOXV", "off")
if BOXV not in ("off", "v2"):
    raise ValueError(f"BOXV={BOXV} not in off/v2")
BOXV_KW = dict(a=0.5, b=1.25, vote=0.75, vm=1, edge=0.5)   # pinned, BOXSTEP.md Phase 1/2
if BOXV == "v2":
    import rawheads_nb2 as rn2  # noqa: E402
    rn2.warm2(**BOXV_KW)
import input_stage  # noqa: E402  (the folder's copy)

CFG_STATS = None
if CFG:
    _ps = importlib.util.spec_from_file_location("patch_cfg", os.path.join(HERE, "patch_cfg.py"))
    patch_cfg = importlib.util.module_from_spec(_ps)
    sys.modules["patch_cfg"] = patch_cfg
    _ps.loader.exec_module(patch_cfg)
    CFG_STATS = patch_cfg.apply()


def chunk_sizes(n, head, tail, chunk):
    """card-pass sizes: head..., chunk..., tail... (tail only if it fits). Same rule as final/submission.py."""
    sizes, rem = [], n
    for h in head:
        if rem <= 0:
            break
        sizes.append(min(h, rem))
        rem -= sizes[-1]
    t = tail if sum(tail) < rem else []
    mid = rem - sum(t)
    return sizes + [chunk] * (mid // chunk) + ([mid % chunk] if mid % chunk else []) + t


def _split(seq, sizes):
    out, i = [], 0
    for s in sizes:
        out.append(seq[i:i + s])
        i += s
    return out


def _tile_index(canvas, tile):
    """rows of the canvas head set [ncell(canvas), 256] that belong to each 2x2 tile, in 320-head order."""
    g0 = canvas // 8
    idx = []
    for t in range(4):
        ty, tx = t // 2, t % 2
        parts, off = [], 0
        for G in (g0, g0 // 2, g0 // 4):
            h = G // 2
            yy, xx = np.meshgrid(np.arange(h), np.arange(h), indexing="ij")
            parts.append((off + (ty * h + yy) * G + tx * h + xx).ravel())
            off += G * G
        idx.append(np.concatenate(parts))
    return idx


TIDX = _tile_index(2 * TILE, TILE) if MOSAIC else None
OFF = [((t // 2) * TILE, (t % 2) * TILE) for t in range(4)]   # (oy, ox) on the canvas
MULTI = BOX == "nbml"
print(f"[{COMBO}] RES={RES} MOSAIC={int(MOSAIC)} ACC={int(ACC)} PREC_FIRST={int(PREC_FIRST)} CFG={int(CFG)} "
      f"BOX={BOX} NMS={NMS} BOXV={BOXV} HEAD={HEAD} TAIL={TAIL} CHUNK={MCHUNK if MOSAIC else input_stage.CHUNK} "
      f"RH_MEM={_e('RH_MEM', 'l1')} GC={GCMODE} DUMP_RAW={DUMP_RAW or '-'}", flush=True)


def _dets(u, W, H, t=None):
    if BOXV == "v2":
        # interior sides of mosaic tile t (1 left, 2 top, 4 right, 8 bottom); 0 = single photo
        em = 0 if t is None else ((t % 2 == 1) * 1 | (t // 2 == 1) * 2 | (t % 2 == 0) * 4 | (t // 2 == 0) * 8)
        cls, box, s = rn2.detections_arrays2(u, W, H, input_stage.CONF_THRESH, NMS, MULTI, 100, em, **BOXV_KW)
    else:
        cls, box, s = rn.detections_arrays(u, W, H, input_stage.CONF_THRESH, NMS, MULTI)
    cats = rn._coco()[cls].tolist()
    return [{"category_id": k, "bbox": b, "score": sc} for k, b, sc in zip(cats, box.tolist(), s.tolist())]


class Submission(res.Submission):
    def run(self, paths):
        paths = list(paths)
        if GCMODE == "freeze":
            gc.freeze()
            gc.disable()
        try:
            keep = {} if DUMP_RAW else None
            out = self._run_mosaic(paths, keep) if MOSAIC else self._run_single(paths, keep)
            self.last_out = out
            self._keep = keep
            return out
        finally:
            if GCMODE == "freeze":
                gc.enable()
                gc.unfreeze()

    # -------------------------------------------------------------- one photo per pass
    def _run_single(self, paths, keep):
        chunks = _split(paths, chunk_sizes(len(paths), HEAD, TAIL, input_stage.CHUNK))
        if not chunks:
            return {}
        futs = {}
        pending = self._submit(chunks[0])
        for i, chunk in enumerate(chunks):
            nxt = self._submit(chunks[i + 1]) if i + 1 < len(chunks) else None
            frames = [f.result() for f in pending]
            pending = nxt
            results = self.pipeline.enqueue([t for t, _, _ in frames]).pop_all()
            for path, (_, W, H), raw in zip(chunk, frames, results):
                futs[path] = self.post_pool.submit(self._post1, raw, W, H, path, keep)
        return {p: f.result() for p, f in futs.items()}

    def _post1(self, raw, W, H, path, keep):
        u = rn.heads_u16(raw)
        if keep is not None:
            keep[path] = (u, W, H)
        return _dets(u, W, H)

    # -------------------------------------------------------------- mosaic: 4 photos per pass
    def _run_mosaic(self, paths, keep):
        quads = [paths[i:i + 4] for i in range(0, len(paths), 4)]
        h4 = [max(1, v // 4) for v in HEAD]
        t4 = [max(1, v // 4) for v in TAIL]
        chunks = _split(quads, chunk_sizes(len(quads), h4, t4, MCHUNK))
        if not chunks:
            return {}
        futs = []
        pending = [self.pool.submit(self._decode_quad, q) for q in chunks[0]]
        for i in range(len(chunks)):
            nxt = [self.pool.submit(self._decode_quad, q) for q in chunks[i + 1]] if i + 1 < len(chunks) else None
            done = [f.result() for f in pending]
            pending = nxt
            results = self.pipeline.enqueue([h for h, _ in done]).pop_all()
            for (_, meta), raw in zip(done, results):
                futs.append(self.post_pool.submit(self._post_quad, raw, meta, keep))
        out = {}
        for f in futs:
            out.update(f.result())
        return out

    def _decode_quad(self, quad):
        import cv2
        import torch
        canvas = np.full((2 * TILE, 2 * TILE, 3), 114, np.uint8)
        meta = []
        for t, p in enumerate(quad):
            f = cv2.imread(p, cv2.IMREAD_COLOR)
            if f is None:
                meta.append((p, 1, 1))
                continue
            H, W = f.shape[:2]
            oy, ox = OFF[t]
            canvas[oy:oy + TILE, ox:ox + TILE] = cv2.resize(f, (TILE, TILE))
            meta.append((p, W, H))
        img = cv2.cvtColor(canvas, cv2.COLOR_BGR2RGB)
        t = torch.from_numpy(img).permute(2, 0, 1).unsqueeze(0).to(torch.bfloat16).contiguous().div_(255.0)
        return self._to_host(t), meta

    def _post_quad(self, raw, meta, keep):
        u = rn.heads_u16(raw)
        if keep is not None:
            keep[meta[0][0]] = (u, meta)
        return {p: _dets(u[TIDX[t]], W, H, t) for t, (p, W, H) in enumerate(meta)}

    def teardown(self):
        keep = getattr(self, "_keep", None)
        if DUMP_RAW and keep:
            vals = list(keep.values())
            np.save(DUMP_RAW + ".u.npy", np.stack([v[0] for v in vals]))
            if MOSAIC:
                meta = {"kind": "mosaic", "tile": TILE,
                        "items": [[[os.path.basename(p), W, H] for p, W, H in v[1]] for v in vals]}
            else:
                meta = {"kind": "single", "items": [[os.path.basename(k), v[1], v[2]] for k, v in keep.items()]}
            meta.update(res=RES, acc=int(ACC), prec_first=int(PREC_FIRST), cfg=int(CFG), conf=input_stage.CONF_THRESH)
            with open(DUMP_RAW + ".json", "w") as f:
                json.dump(meta, f)
            print(f"[sub_matrix] DUMP_RAW wrote {len(vals)} entries to {DUMP_RAW}.u.npy", flush=True)
        super().teardown()
